"use server";

import { cookies } from "next/headers";
import { redirect } from "next/navigation";

const BACKEND_URL = process.env.NEXT_PUBLIC_BACKEND_URL || "http://localhost:5000";

export async function loginAdmin(formData: FormData) {
    const username = formData.get("username");
    const password = formData.get("password");

    try {
        const response = await fetch(`${BACKEND_URL}/admin-auth/login`, {
            method: "POST",
            headers: {
                "Content-Type": "application/json",
            },
            body: JSON.stringify({ username, password }),
        });

        const data = await response.json();

        if (data.success) {
            const cookieStore = await cookies();
            
            // The backend already sets the cookie in the response, 
            // but for Next.js Server Components / Actions, we might need to manually handle 
            // the session if we want to use 'isAdminAuthenticated' helper efficiently 
            // or if the backend cookie isn't being passed through to the browser correctly in this dev setup.
            
            // However, the best way is to let the backend handle the cookie, 
            // but since we are using 'use server' actions, we can set a session cookie here too.
            cookieStore.set("admin_session", "authenticated", {
                httpOnly: true,
                secure: process.env.NODE_ENV === "production",
                maxAge: 60 * 60 * 24, // 1 day
                path: "/",
            });

            return { success: true };
        } else {
            return { success: false, error: data.error || data.message || "Authentication failed" };
        }
    } catch (error) {
        console.error("Login Error:", error);
        return { success: false, error: "Unable to connect to administration server" };
    }
}

export async function logoutAdmin() {
    const cookieStore = await cookies();
    cookieStore.delete("admin_session");
    redirect("/admin");
}

export async function createAdmin(adminData: any) {
    const cookieStore = await cookies();
    const adminToken = cookieStore.get("admin_access_token")?.value;
    const userToken = cookieStore.get("accessToken")?.value;

    let cookieHeader = "";
    if (adminToken) cookieHeader += `admin_access_token=${adminToken}; `;
    if (userToken) cookieHeader += `accessToken=${userToken}; `;

    try {
        const response = await fetch(`${BACKEND_URL}/admin-auth/create-admin`, {
            method: "POST",
            headers: {
                "Content-Type": "application/json",
                "Cookie": cookieHeader
            },
            body: JSON.stringify(adminData),
        });

        const data = await response.json();

        if (data.success) {
            return { success: true, message: data.message };
        } else {
            return { success: false, error: data.error || data.message || "Failed to create administrator" };
        }
    } catch (error) {
        console.error("Create Admin Error:", error);
        return { success: false, error: "Unable to connect to administration server" };
    }
}

export async function getAdminProfile() {
    const cookieStore = await cookies();
    const adminToken = cookieStore.get("admin_access_token")?.value;
    const userToken = cookieStore.get("accessToken")?.value;

    let cookieHeader = "";
    if (adminToken) cookieHeader += `admin_access_token=${adminToken}; `;
    if (userToken) cookieHeader += `accessToken=${userToken}; `;

    try {
        const response = await fetch(`${BACKEND_URL}/admin-auth/me`, {
            method: "GET",
            headers: {
                "Content-Type": "application/json",
                "Cookie": cookieHeader
            },
        });

        const data = await response.json();
        return data.success ? data.admin : null;
    } catch (error) {
        console.error("Get Profile Error:", error);
        return null;
    }
}

export async function isAdminAuthenticated() {
    const cookieStore = await cookies();
    return cookieStore.get("admin_session")?.value === "authenticated";
}
