"use client";

import { useState, useEffect } from "react";
import { Card, CardContent, CardHeader, CardTitle } from "../../components/ui/card";
import { 
    Users, Package, ShoppingCart, TrendingUp, ArrowUpRight, 
    ArrowDownRight, Clock, Activity, ShieldCheck, Zap, 
    Plus, X, ShieldAlert, Mail, Lock, Phone, UserPlus
} from "lucide-react";
import { getAdminProfile, createAdmin } from "../../lib/admin-actions";
import { Button } from "@/app/components/ui/button";
import { Input } from "@/app/components/ui/input";
import { Label } from "@/app/components/ui/label";
import ErrorMessage from "../../components/shared/ErrorMessage";

export default function AdminDashboard() {
    const [adminProfile, setAdminProfile] = useState<any>(null);
    const [isAddModalOpen, setIsAddModalOpen] = useState(false);
    const [formLoading, setFormLoading] = useState(false);
    const [formError, setFormError] = useState<string | null>(null);
    const [formSuccess, setFormSuccess] = useState<string | null>(null);

    useEffect(() => {
        const fetchProfile = async () => {
            const profile = await getAdminProfile();
            setAdminProfile(profile);
        };
        fetchProfile();
    }, []);

    const stats = [
        { label: "Total Users", value: "1,284", icon: Users, change: "+12%", trendingUp: true, color: "text-blue-500" },
        { label: "Active Listings", value: "432", icon: Package, change: "+5.4%", trendingUp: true, color: "text-emerald-500" },
        { label: "Total Transactions", value: "856", icon: ShoppingCart, change: "-2.1%", trendingUp: false, color: "text-amber-500" },
        { label: "Revenue", value: "Rs. 1,24,500", icon: TrendingUp, change: "+4.3%", trendingUp: true, color: "text-rose-500" },
    ];

    const recentActivity = [
        { id: 1, user: "Alice Johnson", action: "listed a new item", target: "iPhone 13 Pro", time: "2 minutes ago", status: "completed" },
        { id: 2, user: "Bob Smith", action: "verified their account", target: null, time: "15 minutes ago", status: "process" },
        { id: 3, user: "Charlie Davis", action: "purchased an item", target: "Mechanical Keyboard", time: "1 hour ago", status: "completed" },
        { id: 4, user: "Diana Prince", action: "reported a listing", target: "Suspicious Item #42", time: "3 hours ago", status: "warning" },
        { id: 5, user: "Evan Wright", action: "updated their profile", target: null, time: "5 hours ago", status: "completed" },
    ];

    async function handleAddAdmin(event: React.FormEvent<HTMLFormElement>) {
        event.preventDefault();
        setFormLoading(true);
        setFormError(null);
        setFormSuccess(null);

        const formData = new FormData(event.currentTarget);
        const adminData = {
            username: formData.get("username"),
            email: formData.get("email"),
            phone: formData.get("phone"),
            password: formData.get("password"),
            role: formData.get("role")
        };

        const result = await createAdmin(adminData);

        if (result.success) {
            setFormSuccess(result.message || "Admin created successfully");
            setTimeout(() => {
                setIsAddModalOpen(false);
                setFormSuccess(null);
            }, 2000);
        } else {
            setFormError(result.error || "Failed to create admin");
        }
        setFormLoading(false);
    }

    return (
        <div className="space-y-8 animate-in fade-in slide-in-from-bottom-4 duration-700 relative">
            
            {/* Add Admin Modal */}
            {isAddModalOpen && (
                <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-zinc-950/80 backdrop-blur-sm animate-in fade-in duration-300">
                    <Card className="w-full max-w-lg bg-zinc-900 border-zinc-800 shadow-2xl relative overflow-hidden">
                        <div className="absolute top-0 left-0 w-full h-1 bg-gradient-to-r from-emerald-500 to-blue-500" />
                        <CardHeader className="flex flex-row items-center justify-between pb-6">
                            <div className="space-y-1">
                                <CardTitle className="text-2xl font-bold text-white flex items-center gap-2">
                                    <UserPlus className="w-6 h-6 text-emerald-500" />
                                    Provision Account
                                </CardTitle>
                                <p className="text-zinc-500 text-sm">Create a new administrative access node</p>
                            </div>
                            <button 
                                onClick={() => setIsAddModalOpen(false)}
                                className="p-2 hover:bg-zinc-800 rounded-full text-zinc-500 hover:text-white transition-colors"
                            >
                                <X className="w-5 h-5" />
                            </button>
                        </CardHeader>
                        <CardContent>
                            <form onSubmit={handleAddAdmin} className="space-y-5">
                                <div className="grid grid-cols-2 gap-4">
                                    <div className="space-y-2">
                                        <Label htmlFor="username" className="text-zinc-400">Username</Label>
                                        <div className="relative">
                                            <Input id="username" name="username" required className="bg-zinc-950 border-zinc-800 focus:border-emerald-500/50" />
                                        </div>
                                    </div>
                                    <div className="space-y-2">
                                        <Label htmlFor="role" className="text-zinc-400">Designation</Label>
                                        <select 
                                            name="role" 
                                            id="role" 
                                            className="w-full h-10 px-3 py-2 bg-zinc-950 border border-zinc-800 rounded-md text-sm text-white focus:outline-none focus:border-emerald-500/50"
                                        >
                                            <option value="admin">Admin</option>
                                            <option value="moderator">Moderator</option>
                                            <option value="superadmin">SuperAdmin</option>
                                        </select>
                                    </div>
                                </div>
                                <div className="space-y-2">
                                    <Label htmlFor="email" className="text-zinc-400">Email Address</Label>
                                    <div className="relative">
                                        <Mail className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-zinc-600" />
                                        <Input id="email" name="email" type="email" placeholder="admin@dosrobazar.com" className="pl-10 bg-zinc-950 border-zinc-800 focus:border-emerald-500/50" />
                                    </div>
                                </div>
                                <div className="space-y-2">
                                    <Label htmlFor="phone" className="text-zinc-400">Contact Number</Label>
                                    <div className="relative">
                                        <Phone className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-zinc-600" />
                                        <Input id="phone" name="phone" placeholder="+977" className="pl-10 bg-zinc-950 border-zinc-800 focus:border-emerald-500/50" />
                                    </div>
                                </div>
                                <div className="space-y-2">
                                    <Label htmlFor="password" className="text-zinc-400">Secret Key (Password)</Label>
                                    <div className="relative">
                                        <Lock className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-zinc-600" />
                                        <Input id="password" name="password" type="password" required className="pl-10 bg-zinc-950 border-zinc-800 focus:border-emerald-500/50" />
                                    </div>
                                </div>

                                {formError && <ErrorMessage error={formError} />}
                                {formSuccess && (
                                    <div className="p-3 bg-emerald-500/10 border border-emerald-500/20 rounded-lg text-emerald-500 text-sm font-bold flex items-center gap-2">
                                        <ShieldCheck className="w-4 h-4" />
                                        {formSuccess}
                                    </div>
                                )}

                                <div className="flex gap-3 pt-2">
                                    <Button 
                                        type="button" 
                                        variant="outline" 
                                        onClick={() => setIsAddModalOpen(false)}
                                        className="flex-1 bg-transparent border-zinc-800 text-zinc-400 hover:bg-zinc-800 hover:text-white"
                                    >
                                        Cancel
                                    </Button>
                                    <Button 
                                        type="submit" 
                                        disabled={formLoading}
                                        className="flex-1 bg-emerald-600 hover:bg-emerald-500 text-white font-bold"
                                    >
                                        {formLoading ? "Provisioning..." : "Add Administrator"}
                                    </Button>
                                </div>
                            </form>
                        </CardContent>
                    </Card>
                </div>
            )}

            {/* Header Section */}
            <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
                <div className="space-y-1">
                    <h1 className="text-4xl font-extrabold tracking-tight text-white bg-clip-text text-transparent bg-gradient-to-r from-white to-zinc-500">
                        System Insights
                    </h1>
                    <p className="text-zinc-500 text-lg flex items-center gap-2">
                        <Activity className="w-4 h-4 text-emerald-500" />
                        Live platform health and performance metrics
                    </p>
                </div>
                <div className="flex items-center gap-4">
                    {/* Only show Add Admin to SuperAdmins */}
                    {adminProfile?.role === 'superadmin' && (
                        <Button 
                            onClick={() => setIsAddModalOpen(true)}
                            className="bg-zinc-100 hover:bg-white text-zinc-950 font-bold px-6 py-6 rounded-2xl flex items-center gap-2 shadow-[0_10px_20px_rgba(255,255,255,0.1)] transition-all hover:scale-105"
                        >
                            <Plus className="w-5 h-5" />
                            Add Administrator
                        </Button>
                    )}
                    
                    <div className="flex flex-col items-end mr-4">
                        <span className="text-xs font-bold text-zinc-500 uppercase tracking-widest">Server Status</span>
                        <span className="text-sm font-bold text-emerald-500 flex items-center gap-1.5">
                            <span className="relative flex h-2 w-2">
                                <span className="animate-ping absolute inline-flex h-full w-full rounded-full bg-emerald-400 opacity-75"></span>
                                <span className="relative inline-flex rounded-full h-2 w-2 bg-emerald-500"></span>
                            </span>
                            Operational
                        </span>
                    </div>
                </div>
            </div>

            {/* Stats Grid */}
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
                {stats.map((stat) => (
                    <Card key={stat.label} className="bg-zinc-900/40 border-zinc-800 hover:border-emerald-500/30 transition-all duration-300 group overflow-hidden relative">
                        <div className="absolute top-0 right-0 p-3 opacity-10 group-hover:scale-110 transition-transform duration-500">
                            <stat.icon className="w-20 h-20" />
                        </div>
                        <CardHeader className="flex flex-row items-center justify-between pb-2">
                            <CardTitle className="text-sm font-semibold text-zinc-400 tracking-wide uppercase">{stat.label}</CardTitle>
                            <stat.icon className={`w-5 h-5 ${stat.color} opacity-80`} />
                        </CardHeader>
                        <CardContent>
                            <div className="text-3xl font-black text-white">{stat.value}</div>
                            <div className={`flex items-center mt-2 text-xs font-bold ${stat.trendingUp ? 'text-emerald-500' : 'text-rose-500'}`}>
                                {stat.trendingUp ? <ArrowUpRight className="w-3 h-3 mr-1" /> : <ArrowDownRight className="w-3 h-3 mr-1" />}
                                {stat.change}
                                <span className="text-zinc-600 font-medium ml-1.5 italic">vs last month</span>
                            </div>
                        </CardContent>
                    </Card>
                ))}
            </div>

            <div className="grid grid-cols-1 xl:grid-cols-3 gap-8">
                {/* Recent Activity */}
                <Card className="xl:col-span-2 bg-zinc-900/20 border-zinc-800 backdrop-blur-sm overflow-hidden">
                    <CardHeader className="border-b border-zinc-900/50 bg-zinc-900/40 py-6">
                        <div className="flex items-center justify-between">
                            <CardTitle className="text-xl text-white flex items-center gap-3">
                                <div className="p-2 rounded-lg bg-emerald-500/10">
                                    <Clock className="w-5 h-5 text-emerald-500" />
                                </div>
                                System Audit Log
                            </CardTitle>
                            <button className="text-xs font-bold text-zinc-500 hover:text-emerald-500 transition-colors uppercase tracking-widest">
                                Live Updates ON
                            </button>
                        </div>
                    </CardHeader>
                    <CardContent className="p-0">
                        <div className="divide-y divide-zinc-900/50">
                            {recentActivity.map((activity) => (
                                <div key={activity.id} className="flex items-center gap-4 p-5 hover:bg-zinc-800/10 transition-all group">
                                    <div className="relative">
                                        <div className="w-12 h-12 rounded-2xl bg-gradient-to-br from-zinc-800 to-zinc-900 border border-zinc-800 flex items-center justify-center font-black text-white group-hover:border-zinc-700 transition-colors">
                                            {activity.user.charAt(0)}
                                        </div>
                                        {activity.status === 'warning' && (
                                            <div className="absolute -top-1 -right-1 w-4 h-4 bg-rose-500 rounded-full border-2 border-zinc-950" />
                                        )}
                                    </div>
                                    <div className="flex-1 min-w-0">
                                        <p className="text-sm text-zinc-300 leading-relaxed">
                                            <span className="font-bold text-white hover:text-emerald-400 cursor-pointer transition-colors">{activity.user}</span> 
                                            <span className="text-zinc-500 mx-1.5">{activity.action}</span>
                                            {activity.target && (
                                                <span className="px-2 py-0.5 rounded-md bg-emerald-500/5 border border-emerald-500/10 text-emerald-500 font-bold text-xs">
                                                    {activity.target}
                                                </span>
                                            )}
                                        </p>
                                        <p className="text-xs text-zinc-600 font-medium mt-1 flex items-center gap-2 uppercase tracking-tight">
                                            <Zap className="w-3 h-3" />
                                            {activity.time}
                                        </p>
                                    </div>
                                    <div className="hidden sm:block">
                                        <button className="px-4 py-2 rounded-xl border border-zinc-800 text-xs font-bold text-zinc-500 hover:border-zinc-700 hover:text-white transition-all">
                                            Investigate
                                        </button>
                                    </div>
                                </div>
                            ))}
                        </div>
                        <div className="p-6 bg-zinc-900/20">
                            <button className="w-full py-4 rounded-2xl bg-zinc-900 border border-zinc-800 text-sm font-bold text-zinc-400 hover:bg-zinc-800 hover:text-white hover:border-emerald-500/30 transition-all shadow-xl">
                                Access Full Forensic Audit History
                            </button>
                        </div>
                    </CardContent>
                </Card>

                {/* Quick Actions & Security */}
                <div className="space-y-8">
                    <Card className="bg-zinc-900/40 border-zinc-800 overflow-hidden relative">
                        <div className="absolute top-0 left-0 w-1 h-full bg-emerald-500" />
                        <CardHeader>
                            <CardTitle className="text-lg text-white font-bold tracking-tight">Rapid Response</CardTitle>
                        </CardHeader>
                        <CardContent className="space-y-4">
                            {[
                                { label: "Generate Intelligence Report", sub: "Export system telemetery", hotkey: "G+R" },
                                { label: "Review Flagged Assets", sub: "12 items pending moderation", hotkey: "R+A", badge: "12" },
                                { label: "Broadcast Network Alert", sub: "Notify all active sessions", hotkey: "B+N" },
                                { label: "Vulnerability Scan", sub: "Last run 4 hours ago", hotkey: "V+S" }
                            ].map((action) => (
                                <button
                                    key={action.label}
                                    className="group w-full flex items-center justify-between p-4 rounded-2xl bg-zinc-900/50 border border-zinc-800 hover:border-emerald-500/50 hover:bg-zinc-800/50 transition-all text-left"
                                >
                                    <div>
                                        <div className="flex items-center gap-2">
                                            <span className="text-sm font-bold text-zinc-300 group-hover:text-white">{action.label}</span>
                                            {action.badge && (
                                                <span className="px-1.5 py-0.5 rounded-full bg-rose-500/10 border border-rose-500/20 text-rose-500 text-[10px] font-black">
                                                    {action.badge}
                                                </span>
                                            )}
                                        </div>
                                        <p className="text-xs text-zinc-600 group-hover:text-zinc-500 font-medium">{action.sub}</p>
                                    </div>
                                    <span className="hidden sm:block text-[10px] font-black text-zinc-700 bg-zinc-950 px-2 py-1 rounded border border-zinc-800 group-hover:text-emerald-500 group-hover:border-emerald-500/30 transition-colors">
                                        {action.hotkey}
                                    </span>
                                </button>
                            ))}
                        </CardContent>
                    </Card>

                    <Card className="bg-emerald-500/5 border border-emerald-500/10 p-6 relative overflow-hidden group">
                        <ShieldCheck className="absolute -bottom-6 -right-6 w-32 h-32 text-emerald-500/5 transform -rotate-12 group-hover:scale-110 transition-transform duration-700" />
                        <div className="relative space-y-3">
                            <h3 className="text-white font-black uppercase tracking-widest text-xs">Security Status</h3>
                            <p className="text-emerald-500/80 text-sm font-medium leading-relaxed">
                                Platform integrity is currently stabilized at <span className="font-bold text-white underline decoration-emerald-500 underline-offset-4">99.8%</span>. No critical breaches detected in last 360 hours.
                            </p>
                            <div className="pt-2">
                                <div className="h-1.5 w-full bg-zinc-900 rounded-full overflow-hidden">
                                    <div className="h-full w-[99.8%] bg-emerald-500 animate-pulse" />
                                </div>
                            </div>
                        </div>
                    </Card>
                </div>
            </div>
        </div>
    );
}
